import{bQ as d,aL as e,u as a,G as r}from"./chunks/framework.CNL6o8_w.js";const b=JSON.parse('{"title":"固件 OTA 地址","description":"","frontmatter":{},"headers":[],"relativePath":"lightsmart/reference/firmware-ota.md","filePath":"lightsmart/reference/firmware-ota.md"}'),o={name:"lightsmart/reference/firmware-ota.md"};function i(h,t,n,l,s,c){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="固件-ota-地址" tabindex="-1">固件 OTA 地址 <a class="header-anchor" href="#固件-ota-地址" aria-label="Permalink to &quot;固件 OTA 地址&quot;">​</a></h1><p>固件信息存储在阿里云 OSS（公共读），小程序通过 <code>firmware/{pid}/upgrade_par.json</code> 检查升级，网关通过 <code>firmware/{pid}/</code> 下载固件二进制文件。</p><h2 id="ota-升级流程" tabindex="-1">OTA 升级流程 <a class="header-anchor" href="#ota-升级流程" aria-label="Permalink to &quot;OTA 升级流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>小程序                          OSS                          网关                        子设备</span></span>
<span class="line"><span>  |                              |                             |                            |</span></span>
<span class="line"><span>  |--- GET firmware/{pid}/upgrade_par.json ---&gt;|               |                            |</span></span>
<span class="line"><span>  |&lt;-- fw_url, fw_ver, ... -------|             |                            |</span></span>
<span class="line"><span>  |                              |                             |                            |</span></span>
<span class="line"><span>  |--- systemPublish(mstype=15) via MQTT -----&gt;|-------------→|                            |</span></span>
<span class="line"><span>  |                              |              |--- 下载 fw_url (HTTP) ----→|             |</span></span>
<span class="line"><span>  |                              |              |&lt;-- 固件二进制 --------------|             |</span></span>
<span class="line"><span>  |                              |              |--- BLE 刷写子设备 -----------------------→|</span></span>
<span class="line"><span>  |&lt;-- register code=2001 (进度) via MQTT ------|-------------|                            |</span></span>
<span class="line"><span>  |                              |              |                             |            |</span></span>
<span class="line"><span>  |                              |              |                             --- 刷写完成 |</span></span>
<span class="line"><span>  |&lt;-- register code=2001 (status=5 升级成功) ---|-------------|                            |</span></span></code></pre></div><h3 id="网关升级-特殊" tabindex="-1">网关升级（特殊） <a class="header-anchor" href="#网关升级-特殊" aria-label="Permalink to &quot;网关升级（特殊）&quot;">​</a></h3><p>网关插座（type=200）的升级方式与子设备不同：</p><ol><li>小程序调用 <code>POST /hotel/device/set_upgrade</code>（携带 <code>file_id</code>）通知后端</li><li>小程序通过 <code>systemPublish(mstype=9)</code> 通知网关执行升级</li><li>网关自行从后端获取固件并刷写</li></ol><p>网关的 <code>upgrade_par.json</code> 中没有 <code>fw_url</code>，而是 <code>file_id</code>（后端通过该 ID 定位固件文件）。</p><h3 id="子设备升级" tabindex="-1">子设备升级 <a class="header-anchor" href="#子设备升级" aria-label="Permalink to &quot;子设备升级&quot;">​</a></h3><p>子设备（开关、窗帘等）的升级通过 <code>systemPublish(mstype=15)</code> 下发指令，固件 <code>fw_url</code> 直接由网关从 OSS 下载（HTTP 公共读）。</p><h2 id="固件地址表" tabindex="-1">固件地址表 <a class="header-anchor" href="#固件地址表" aria-label="Permalink to &quot;固件地址表&quot;">​</a></h2><blockquote><p>OSS 基础路径：<code>http://chint-beancomm-content.oss-cn-shanghai.aliyuncs.com</code></p><p>固件元数据：<code>/firmware/{pid}/upgrade_par.json</code>（JSON，公共读）</p><p>固件二进制：<code>/firmware/{pid}/{fw_name}</code>（bin 文件，公共读）</p></blockquote><h3 id="网关插座" tabindex="-1">网关插座 <a class="header-anchor" href="#网关插座" aria-label="Permalink to &quot;网关插座&quot;">​</a></h3><table tabindex="0"><thead><tr><th>pid</th><th>type</th><th>型号</th><th>固件版本</th><th>file_id</th><th style="text-align:center;">强制升级</th><th>说明</th></tr></thead><tbody><tr><td>200</td><td>200</td><td>T7-21600</td><td>1.2.3</td><td>253</td><td style="text-align:center;">是</td><td><code>&lt;1.0.0</code> 需先通过线下 APP 升级</td></tr></tbody></table><blockquote><p>网关无 <code>fw_url</code>，固件由后端通过 <code>file_id</code> 推送。</p></blockquote><h3 id="开关类-yizsw" tabindex="-1">开关类（YiZSW） <a class="header-anchor" href="#开关类-yizsw" aria-label="Permalink to &quot;开关类（YiZSW）&quot;">​</a></h3><p>开关类设备共用 <code>YiZSW</code> 固件，按按键数量区分 pid。8xx 为新一代（BCB22 芯片），84x 为同代 ADC 版本。</p><h4 id="一位开关-type-12-subtype-1" tabindex="-1">一位开关（type=12, subType=1） <a class="header-anchor" href="#一位开关-type-12-subtype-1" aria-label="Permalink to &quot;一位开关（type=12, subType=1）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>pid</th><th>型号</th><th>固件版本</th><th>固件文件</th><th style="text-align:center;">强制升级</th></tr></thead><tbody><tr><td>821</td><td>T7-70100</td><td>1.1.5</td><td><code>BCB22_YiZSW_V115_ADC_OTA_00.bin</code></td><td style="text-align:center;">是</td></tr><tr><td>841</td><td>T7-70100</td><td>1.1.9</td><td><code>BCB22_YiZSW_V119_ADC_OTA_00.bin</code></td><td style="text-align:center;">是</td></tr></tbody></table><h4 id="二位开关-type-12-subtype-2" tabindex="-1">二位开关（type=12, subType=2） <a class="header-anchor" href="#二位开关-type-12-subtype-2" aria-label="Permalink to &quot;二位开关（type=12, subType=2）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>pid</th><th>型号</th><th>固件版本</th><th>固件文件</th><th style="text-align:center;">强制升级</th></tr></thead><tbody><tr><td>822</td><td>T7-70200</td><td>1.1.4</td><td><code>BCB22_YiZSW_V114_OTA_00.bin</code></td><td style="text-align:center;">是</td></tr><tr><td>842</td><td>T7-70200</td><td>1.1.9</td><td><code>BCB22_YiZSW_V119_ADC_OTA_00.bin</code></td><td style="text-align:center;">是</td></tr></tbody></table><h4 id="三位开关-type-12-subtype-3" tabindex="-1">三位开关（type=12, subType=3） <a class="header-anchor" href="#三位开关-type-12-subtype-3" aria-label="Permalink to &quot;三位开关（type=12, subType=3）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>pid</th><th>型号</th><th>固件版本</th><th>固件文件</th><th style="text-align:center;">强制升级</th></tr></thead><tbody><tr><td>823</td><td>T7-70300</td><td>1.1.8</td><td><code>BCB22_YiZSW_V118_ADC_OTA_00.bin</code></td><td style="text-align:center;">是</td></tr><tr><td>843</td><td>T7-70300</td><td>1.1.9</td><td><code>BCB22_YiZSW_V119_ADC_OTA_00.bin</code></td><td style="text-align:center;">是</td></tr></tbody></table><h4 id="四位开关-type-1-subtype-4" tabindex="-1">四位开关（type=1, subType=4） <a class="header-anchor" href="#四位开关-type-1-subtype-4" aria-label="Permalink to &quot;四位开关（type=1, subType=4）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>pid</th><th>型号</th><th>固件版本</th><th>固件文件</th><th style="text-align:center;">强制升级</th></tr></thead><tbody><tr><td>824</td><td>T7-70400</td><td>1.1.4</td><td><code>BCB22_YiZSW_V114_OTA_00.bin</code></td><td style="text-align:center;">是</td></tr><tr><td>844</td><td>T7-70400</td><td>1.1.9</td><td><code>BCB22_YiZSW_V119_ADC_OTA_00.bin</code></td><td style="text-align:center;">是</td></tr></tbody></table><blockquote><p>开关类设备有 <code>&lt;1.1.0</code> 版本限制：低于 1.1.0 的版本需先通过线下 APP 升级。</p></blockquote><h3 id="窗帘类" tabindex="-1">窗帘类 <a class="header-anchor" href="#窗帘类" aria-label="Permalink to &quot;窗帘类&quot;">​</a></h3><h4 id="一位窗帘开关-type-43-subtype-1" tabindex="-1">一位窗帘开关（type=43, subType=1） <a class="header-anchor" href="#一位窗帘开关-type-43-subtype-1" aria-label="Permalink to &quot;一位窗帘开关（type=43, subType=1）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>pid</th><th>型号</th><th>固件版本</th><th>固件文件</th><th style="text-align:center;">强制升级</th></tr></thead><tbody><tr><td>827</td><td>T7-72100</td><td>1.1.4</td><td><code>BCB22_YiZCT_V114_OTA_00.bin</code></td><td style="text-align:center;">是</td></tr><tr><td>847</td><td>T7-72100</td><td>1.1.8</td><td><code>BCB22_YiZCT_V118_ADC_OTA_00.bin</code></td><td style="text-align:center;">是</td></tr></tbody></table><h4 id="二位窗帘开关-type-43-subtype-2" tabindex="-1">二位窗帘开关（type=43, subType=2） <a class="header-anchor" href="#二位窗帘开关-type-43-subtype-2" aria-label="Permalink to &quot;二位窗帘开关（type=43, subType=2）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>pid</th><th>型号</th><th>固件版本</th><th>固件文件</th><th style="text-align:center;">强制升级</th></tr></thead><tbody><tr><td>828</td><td>T7-72200</td><td>1.1.4</td><td><code>BCB22_YiZCT_V114_OTA_00.bin</code></td><td style="text-align:center;">是</td></tr><tr><td>848</td><td>T7-72200</td><td>1.1.8</td><td><code>BCB22_YiZCT_V118_ADC_OTA_00.bin</code></td><td style="text-align:center;">是</td></tr></tbody></table><h4 id="窗帘电机-type-5-subtype-0" tabindex="-1">窗帘电机（type=5, subType=0） <a class="header-anchor" href="#窗帘电机-type-5-subtype-0" aria-label="Permalink to &quot;窗帘电机（type=5, subType=0）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>pid</th><th>型号</th><th>固件版本</th><th>固件文件</th><th style="text-align:center;">强制升级</th></tr></thead><tbody><tr><td>830</td><td>T7-Q50020</td><td>2.0.1</td><td><code>BCB22_YiCTW_V201_251208.bin</code></td><td style="text-align:center;">否</td></tr></tbody></table><h3 id="其他设备" tabindex="-1">其他设备 <a class="header-anchor" href="#其他设备" aria-label="Permalink to &quot;其他设备&quot;">​</a></h3><h4 id="调光调色开关-type-42-subtype-1" tabindex="-1">调光调色开关（type=42, subType=1） <a class="header-anchor" href="#调光调色开关-type-42-subtype-1" aria-label="Permalink to &quot;调光调色开关（type=42, subType=1）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>pid</th><th>固件版本</th><th>固件文件</th><th style="text-align:center;">强制升级</th></tr></thead><tbody><tr><td>826</td><td>1.1.0</td><td><code>BCB22_YiZDM_V110_ADC_OTA_00.bin</code></td><td style="text-align:center;">否</td></tr></tbody></table><h4 id="筒射灯-type-4-subtype-0" tabindex="-1">筒射灯（type=4, subType=0） <a class="header-anchor" href="#筒射灯-type-4-subtype-0" aria-label="Permalink to &quot;筒射灯（type=4, subType=0）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>pid</th><th>固件版本</th><th>固件文件</th><th style="text-align:center;">强制升级</th></tr></thead><tbody><tr><td>829</td><td>1.1.1</td><td><code>BCB22_YiZLT_V111_OTA_00.bin</code></td><td style="text-align:center;">否</td></tr></tbody></table><h4 id="四位开关-旧版-bcb02-芯片" tabindex="-1">四位开关（旧版 BCB02 芯片） <a class="header-anchor" href="#四位开关-旧版-bcb02-芯片" aria-label="Permalink to &quot;四位开关（旧版 BCB02 芯片）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>pid</th><th>固件版本</th><th>固件文件</th><th style="text-align:center;">强制升级</th></tr></thead><tbody><tr><td>7027005</td><td>2.2.9</td><td><code>BCB02(TL)_BduSW_V2.2.9_STD_Pri_Proxy_12.bin</code></td><td style="text-align:center;">否</td></tr></tbody></table><blockquote><p>旧版固件路径在 <code>/assets/firmware/7027005/V229/</code> 下，与新版 <code>/firmware/{pid}/</code> 不同。</p></blockquote><h2 id="upgrade-par-json-字段说明" tabindex="-1">upgrade_par.json 字段说明 <a class="header-anchor" href="#upgrade-par-json-字段说明" aria-label="Permalink to &quot;upgrade_par.json 字段说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>fw_url</code></td><td>string</td><td>固件二进制下载地址（子设备有，网关无）</td></tr><tr><td><code>fw_name</code></td><td>string</td><td>固件文件名</td></tr><tr><td><code>fw_ver</code></td><td>string</td><td>固件版本号</td></tr><tr><td><code>fw_note</code></td><td>string</td><td>更新说明</td></tr><tr><td><code>dev_name</code></td><td>string[]</td><td>设备名称标识（如 <code>YiZSW</code>、<code>YiZCT</code>、<code>YiCTW</code>）</td></tr><tr><td><code>force</code></td><td>boolean</td><td>是否强制升级（非必须）</td></tr><tr><td><code>force1</code></td><td>boolean</td><td>是否强制升级（开关/窗帘类使用）</td></tr><tr><td><code>file_id</code></td><td>number</td><td>固件文件 ID（仅网关，后端通过此 ID 定位固件）</td></tr><tr><td><code>&lt;{version}</code></td><td>string</td><td>低于该版本的提示信息（如 <code>&lt;1.1.0</code>）</td></tr></tbody></table><h2 id="固件命名规则" tabindex="-1">固件命名规则 <a class="header-anchor" href="#固件命名规则" aria-label="Permalink to &quot;固件命名规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前缀</th><th>芯片</th><th>设备类型</th></tr></thead><tbody><tr><td><code>BCB22_YiZSW</code></td><td>BCB22</td><td>开关（一位/二位/三位/四位）</td></tr><tr><td><code>BCB22_YiZCT</code></td><td>BCB22</td><td>窗帘开关（一位/二位）</td></tr><tr><td><code>BCB22_YiCTW</code></td><td>BCB22</td><td>窗帘电机</td></tr><tr><td><code>BCB22_YiZDM</code></td><td>BCB22</td><td>调光调色开关</td></tr><tr><td><code>BCB22_YiZLT</code></td><td>BCB22</td><td>筒射灯</td></tr><tr><td><code>BCB02(TL)_BduSW</code></td><td>BCB02</td><td>旧版四位开关</td></tr></tbody></table><blockquote><p><code>BCB22</code> 为新一代芯片，<code>BCB02</code> 为旧一代芯片。同一设备类型可能有两个 pid 对应新旧两代硬件。</p></blockquote><h2 id="pid-与设备类型映射" tabindex="-1">pid 与设备类型映射 <a class="header-anchor" href="#pid-与设备类型映射" aria-label="Permalink to &quot;pid 与设备类型映射&quot;">​</a></h2><p>pid 到 <code>type</code>/<code>subType</code> 的映射定义在 ztUtil SDK 的 <a href="https://github.com/chintiot/app-lightsmart-ztutil/blob/master/src/protocol.js" target="_blank" rel="noreferrer">protocol.js</a> 中（<code>pidToType</code> 函数）。</p><table tabindex="0"><thead><tr><th>pid</th><th>type</th><th>subType</th><th>设备</th></tr></thead><tbody><tr><td>200</td><td>200</td><td>-</td><td>网关插座</td></tr><tr><td>821 / 841</td><td>12</td><td>1</td><td>一位开关</td></tr><tr><td>822 / 842</td><td>12</td><td>2</td><td>二位开关</td></tr><tr><td>823 / 843</td><td>12</td><td>3</td><td>三位开关</td></tr><tr><td>824 / 844</td><td>1</td><td>4</td><td>四位开关</td></tr><tr><td>825 / 845</td><td>41</td><td>0</td><td>调光开关</td></tr><tr><td>826 / 846</td><td>42</td><td>1</td><td>调光调色开关</td></tr><tr><td>827 / 847</td><td>43</td><td>1</td><td>一位窗帘开关</td></tr><tr><td>828 / 848</td><td>43</td><td>2</td><td>二位窗帘开关</td></tr><tr><td>829</td><td>4</td><td>0</td><td>筒射灯</td></tr><tr><td>830</td><td>5</td><td>0</td><td>窗帘电机</td></tr></tbody></table><blockquote><p>8xx 与 84x 系列对应同一设备类型的不同硬件批次（84x 为 ADC 版本）。</p></blockquote>`,50)])])}const y=d(o,[["render",i]]);export{b as __pageData,y as default};
